const source = $('Execute Workflow Trigger').item.json || {};
const msg = source.message || source.body?.message || source.payload?.message || {};
const chatId = source.chatId || msg.chat?.id || source.payload?.chatId || source.body?.chatId || '';
const owner = String($env.OWNER_DISPLAY_NAME || 'User').trim();

const text = [
  `Google Drive hiện cho phép Mia hỗ trợ ${owner} ở các việc như xem file gần đây, tìm file hoặc thư mục, xem thông tin file, tạo folder, tạo file, chia sẻ, đổi tên, di chuyển và xoá file.`,
  '',
  `${owner} có thể bắt đầu bằng mấy câu như:`,
  '- xem file drive',
  '- tìm file hợp đồng',
  '- thông tin file note.md',
  '- tạo folder Khách hàng',
  '- tạo file ghi-chu.txt nội dung Xin chào',
  '- đổi tên file old.txt thành new.txt',
  '- di chuyển file A vào folder B',
].join('\n');

return [{ json: { chatId, text } }];
